INSERT INTO colaboradores_sedes (colaboradorId, sedeId, creadoEn) SELECT c.id, s.id, '2026-08-25 13:00:00.000' FROM colaboradores c JOIN sedes s ON s.empresaId = 'cmsvhm2jn00l41146esg4o6y0' AND s.nombre = 'Sede principal' AND s.activa = 1 WHERE c.empresaId = 'cmsvhm2jn00l41146esg4o6y0' AND c.id LIKE 'demosept-col-%';
INSERT INTO dias_esperados (id, colaboradorId, fecha, programado, horaEntrada, horaSalida, toleranciaMin, almuerzoMin, minutosEsperados, horarioId, origen, creadoEn, actualizadoEn, toleranciaSalidaMin, ajustaEntrada, almuerzoInicio, almuerzoFin, descansos, plantillaId, esDescanso, descansoPintado) SELECT CONCAT('demosept-d-', SUBSTRING(c.id, 14, 2), '-', DATE_FORMAT(d.fecha, '%m%d')), c.id, d.fecha, d.programado, d.horaEntrada, d.horaSalida, d.toleranciaMin, d.almuerzoMin, d.minutosEsperados, d.horarioId, d.origen, '2026-08-25 13:00:00.000', '2026-08-25 13:00:00.000', d.toleranciaSalidaMin, d.ajustaEntrada, d.almuerzoInicio, d.almuerzoFin, d.descansos, d.plantillaId, d.esDescanso, d.descansoPintado FROM dias_esperados d CROSS JOIN colaboradores c WHERE d.colaboradorId = 'cmt3sq303019e1146irw2bmlo' AND d.fecha >= '2026-09-01 05:00:00.000' AND d.fecha < '2026-10-01 05:00:00.000' AND c.empresaId = 'cmsvhm2jn00l41146esg4o6y0' AND c.id LIKE 'demosept-col-%';
UPDATE dias_esperados a JOIN dias_esperados s ON s.colaboradorId = 'cmt3sq303019e1146irw2bmlo' AND s.fecha = a.fecha SET a.programado = s.programado, a.horaEntrada = s.horaEntrada, a.horaSalida = s.horaSalida, a.toleranciaMin = s.toleranciaMin, a.almuerzoMin = s.almuerzoMin, a.minutosEsperados = s.minutosEsperados, a.horarioId = s.horarioId, a.actualizadoEn = '2026-10-14 12:00:00.000' WHERE a.colaboradorId = 'cmtadsuzu008bhzxcwl6ylipa' AND a.fecha >= '2026-09-01 05:00:00.000' AND a.fecha < '2026-09-16 05:00:00.000' AND a.programado = 0 AND a.horarioId IS NULL;
